// Fork of "Abstract Graphic" by wyatt. https://shadertoy.com/view/MXVyzy
// 2025-01-09 04:05:38

Main {
    Q = vec4(0);
    for (float i = 0.; i < 40.; i++) {
    if (iFrame%120<60) {
        float x = R.x-(R.x-U.x)/(.5+.1*i);
        if (x > 0.) {
        vec4 q = A(vec2(x,i+.5))/float(iFrame+2);
        Q += sin(1.-i/40.*3.2+vec4(1,2,3,4))*exp(-.5*abs(U.y-q.x*R.y*.6));
       }
   } else {
        vec4 q = A(vec2(R.x-(R.x-U.x),i+.5))/float(iFrame+2);
        Q += sin(1.-i/40.*3.2+vec4(1,2,3,4))*exp(-.5*abs(U.y-q.x*R.y*.6));
    }
    }
}

#define SCALE (.5+.1*U.y)

            #define K1 .001*SCALE
            #define K2 .5
Main {

   Q = A(U);
   vec3 p = vec3(U.x,0,0);
   vec3 v = vec3(0);
    if (iFrame < 1) {
        Q = vec4(0);
        Q.y = 1.;
        for (float i = U.x; i < R.x; i++) {
            Q.y *= 1.-K1;
        }
    }
    else {
        for (float i = 0.; i < 200.; i++) {
            if (p.x>R.x) break;
            vec4 q = A(vec2(max(p.x,0.),U.y));
            Q.x += q.y*exp(-3.*length(v-vec3(-1,0,0)));
            float a = 10.;
            p += a/SCALE*v*inversesqrt(1.+a*a*dot(v,v));
            v += K2*(hash(vec4(1,1,i,iFrame)).xyz*2.-1.);
        }
    }


}
